# --- Test: Color Contrast (Basic) ---
class TestColorContrast:
    def test_swarm_colors_have_contrast(self):
        """Verify Swarm colors meet WCAG AA contrast ratio (4.5:1) for text."""
        # Simple luminance calculation for hex colors
        def relative_luminance(hex_color):
            hex_color = hex_color.lstrip("#")
            r, g, b = (int(hex_color[i:i+2], 16) / 255 for i in (0, 2, 4))
            def linearize(c):
                return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
            r, g, b = linearize(r), linearize(g), linearize(b)
            return 0.2126 * r + 0.7152 * g + 0.0722 * b

        def contrast_ratio(c1, c2):
            l1, l2 = relative_luminance(c1), relative_luminance(c2)
            lighter, darker = max(l1, l2), min(l1, l2)
            return (lighter + 0.05) / (darker + 0.05)

        # Test swarm-medium vs swarm-light (text on background)
        ratio = contrast_ratio(EXPECTED_COLORS["swarm-medium"], EXPECTED_COLORS["swarm-light"])
        assert ratio >= 4.5, f"Contrast ratio {ratio:.2f} below WCAG AA (4.5:1)"

        # Test swarm-accent vs swarm-medium (accent on dark)
        ratio_accent = contrast_ratio(EXPECTED_COLORS["swarm-accent"], EXPECTED_COLORS["swarm-medium"])
        assert ratio_accent >= 3.0, f"Accent contrast {ratio_accent:.2f} below WCAG AA large text (3:1)"


